import{_ as l,C as n,o as a,c as o,a7 as i,b as s,w as t,a as h,E as d,a8 as u}from"./chunks/framework.DmcojIVA.js";const k=JSON.parse('{"title":"分布式系统：从不可靠组件构建可靠服务","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/distributed-system/index.md","filePath":"development/common/distributed-system/index.md","lastUpdated":1785428463000}'),c={name:"development/common/distributed-system/index.md"};function E(b,e,g,f,m,p){const r=n("Mermaid");return a(),o("div",null,[e[1]||(e[1]=i('<h1 id="fen-bu-shi-xi-tongcong-bu-ke-kao-zu-jian-gou-jian-ke-kao-fu-wu" tabindex="-1">分布式系统：从不可靠组件构建可靠服务 <a class="header-anchor" href="#fen-bu-shi-xi-tongcong-bu-ke-kao-zu-jian-gou-jian-ke-kao-fu-wu" aria-label="Permalink to &quot;分布式系统：从不可靠组件构建可靠服务&quot;">​</a></h1><p>分布式系统由多个通过网络协作的计算节点组成。对使用者来说，它通常表现为一个完整系统；对设计者来说，却必须同时面对节点独立故障、网络延迟、消息乱序、并发写入和时钟偏差。</p><p>学习分布式系统的关键，不是背诵中间件名称，而是建立一个基本认识：</p><blockquote><p>网络会延迟或中断，进程会暂停或崩溃，消息可能重复，任何节点看到的都只是局部事实。</p></blockquote><h2 id="wei-shi-me-fen-bu-shi-xi-tong-nan" tabindex="-1">为什么分布式系统难 <a class="header-anchor" href="#wei-shi-me-fen-bu-shi-xi-tong-nan" aria-label="Permalink to &quot;为什么分布式系统难&quot;">​</a></h2><h3 id="ju-bu-gu-zhang" tabindex="-1">局部故障 <a class="header-anchor" href="#ju-bu-gu-zhang" aria-label="Permalink to &quot;局部故障&quot;">​</a></h3><p>单机程序崩溃时，故障通常是明确的；分布式系统则可能只有某个节点、某条链路或某个可用区异常。调用方超时并不等于操作失败：请求可能没有到达，也可能已经成功执行，只是响应丢失。</p><p>这也是支付、下单等接口需要设计<strong>幂等性</strong>的原因。重试是一种恢复手段，但没有幂等约束的重试可能放大故障。</p><p>下面的时序图展示了最容易误判的情况：服务端已经提交事务，但响应丢失，客户端看到的只有超时。</p>',9)),(a(),s(u,null,{default:t(()=>[d(r,{id:"mermaid-29",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20C%20as%20%E5%AE%A2%E6%88%B7%E7%AB%AF%0A%20%20%20%20participant%20O%20as%20%E8%AE%A2%E5%8D%95%E6%9C%8D%E5%8A%A1%0A%20%20%20%20participant%20D%20as%20%E6%95%B0%E6%8D%AE%E5%BA%93%0A%20%20%20%20C-%3E%3EO%3A%20%E5%88%9B%E5%BB%BA%E8%AE%A2%E5%8D%95%EF%BC%88%E5%B9%82%E7%AD%89%E9%94%AE%20k1%EF%BC%89%0A%20%20%20%20O-%3E%3ED%3A%20%E5%86%99%E5%85%A5%E8%AE%A2%E5%8D%95%0A%20%20%20%20D--%3E%3EO%3A%20%E4%BA%8B%E5%8A%A1%E6%8F%90%E4%BA%A4%E6%88%90%E5%8A%9F%0A%20%20%20%20Note%20over%20O%2CC%3A%20%E5%93%8D%E5%BA%94%E5%9C%A8%E7%BD%91%E7%BB%9C%E4%B8%AD%E4%B8%A2%E5%A4%B1%EF%BC%8C%E5%AE%A2%E6%88%B7%E7%AB%AF%E8%B6%85%E6%97%B6%0A%20%20%20%20C-%3E%3EO%3A%20%E4%BD%BF%E7%94%A8%E5%B9%82%E7%AD%89%E9%94%AE%20k1%20%E9%87%8D%E8%AF%95%0A%20%20%20%20O-%3E%3ED%3A%20%E6%9F%A5%E8%AF%A2%20k1%20%E7%9A%84%E5%B7%B2%E6%9C%89%E7%BB%93%E6%9E%9C%0A%20%20%20%20D--%3E%3EO%3A%20%E8%BF%94%E5%9B%9E%E5%B7%B2%E5%88%9B%E5%BB%BA%E8%AE%A2%E5%8D%95%0A%20%20%20%20O--%3E%3EC%3A%20%E8%BF%94%E5%9B%9E%E7%AC%AC%E4%B8%80%E6%AC%A1%E6%93%8D%E4%BD%9C%E7%9A%84%E7%BB%93%E6%9E%9C%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<blockquote><p>图示参考：<a href="https://aws.amazon.com/builders-library/timeouts-retries-and-backoff-with-jitter/" target="_blank" rel="noreferrer">Amazon Builders&#39; Library：Timeouts, retries and backoff with jitter</a></p></blockquote><h3 id="mei-you-quan-ju-shi-zhong" tabindex="-1">没有全局时钟 <a class="header-anchor" href="#mei-you-quan-ju-shi-zhong" aria-label="Permalink to &quot;没有全局时钟&quot;">​</a></h3><p>不同机器的物理时钟存在偏差，不能仅凭两个本地时间戳断言事件的因果顺序。Lamport 在经典论文中用 <em>happened-before</em> 关系和逻辑时钟描述事件的偏序关系，为复制、快照和一致性协议奠定了基础。</p><h3 id="bing-fa-yu-zhuang-tai-fu-zhi" tabindex="-1">并发与状态复制 <a class="header-anchor" href="#bing-fa-yu-zhuang-tai-fu-zhi" aria-label="Permalink to &quot;并发与状态复制&quot;">​</a></h3><p>多个节点可能同时接受写入，而复制存在延迟。系统必须回答：</p><ul><li>哪个副本可以接受写入？</li><li>何时可以向客户端确认成功？</li><li>读请求允许看到多旧的数据？</li><li>冲突由系统拒绝、排序，还是交给业务合并？</li></ul><p>这些问题共同决定系统的一致性模型，而不是由“用了分布式数据库”自动解决。</p><h3 id="wang-luo-fen-qu-xia-bi-xu-zuo-qu-she" tabindex="-1">网络分区下必须做取舍 <a class="header-anchor" href="#wang-luo-fen-qu-xia-bi-xu-zuo-qu-she" aria-label="Permalink to &quot;网络分区下必须做取舍&quot;">​</a></h3><p>CAP 定理讨论的是：在发生网络分区时，一个系统无法同时保证线性一致性和每个请求都得到非错误响应。工程上的问题不是笼统地“从三个字母中选两个”，而是明确：</p><ul><li>哪些操作在分区期间拒绝服务，以保护一致性？</li><li>哪些操作可以接受旧值或冲突，以维持可用性？</li><li>分区恢复后如何检测并解决差异？</li></ul><h3 id="gu-zhang-ke-neng-bei-fang-da" tabindex="-1">故障可能被放大 <a class="header-anchor" href="#gu-zhang-ke-neng-bei-fang-da" aria-label="Permalink to &quot;故障可能被放大&quot;">​</a></h3><p>超时、重试和自动扩缩容如果缺少边界，可能形成重试风暴、排队膨胀或级联故障。可靠性设计不仅要考虑组件能否恢复，还要考虑恢复动作是否会给下游增加压力。</p><h2 id="he-xin-zhi-shi-di-tu" tabindex="-1">核心知识地图 <a class="header-anchor" href="#he-xin-zhi-shi-di-tu" aria-label="Permalink to &quot;核心知识地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>要解决的问题</th><th>常见机制</th></tr></thead><tbody><tr><td>通信</td><td>节点如何交换信息</td><td>RPC、消息队列、超时、重试、背压</td></tr><tr><td>数据分片</td><td>数据如何分散到多个节点</td><td>哈希分片、范围分片、一致性哈希</td></tr><tr><td>数据复制</td><td>节点故障后如何继续提供数据</td><td>主从、多主、无主复制、法定人数</td></tr><tr><td>一致性</td><td>客户端能看到什么结果</td><td>线性一致性、因果一致性、最终一致性</td></tr><tr><td>协调与共识</td><td>多个节点如何对顺序或值达成一致</td><td>Leader 选举、Raft、Paxos、租约</td></tr><tr><td>容错</td><td>如何限制和恢复故障</td><td>幂等、熔断、限流、隔离、降级</td></tr><tr><td>可观测性</td><td>如何从外部理解系统内部状态</td><td>指标、日志、链路、事件、性能剖析</td></tr></tbody></table><p>这些主题彼此关联。例如，一个带重试的 RPC 同时涉及通信、幂等、一致性和可观测性；一个复制数据库同时涉及分片、故障检测、共识和恢复。</p><h2 id="yi-ge-shi-yong-de-fen-xi-kuang-jia" tabindex="-1">一个实用的分析框架 <a class="header-anchor" href="#yi-ge-shi-yong-de-fen-xi-kuang-jia" aria-label="Permalink to &quot;一个实用的分析框架&quot;">​</a></h2><p>遇到新的分布式系统或故障场景时，可以依次问下面五组问题。</p><h3 id="1-zhuang-tai-zai-na-li" tabindex="-1">1. 状态在哪里 <a class="header-anchor" href="#1-zhuang-tai-zai-na-li" aria-label="Permalink to &quot;1. 状态在哪里&quot;">​</a></h3><ul><li>哪些组件有状态，哪些组件可以随时重建？</li><li>数据有几个副本，副本分布在哪里？</li><li>谁是事实来源（source of truth）？</li></ul><h3 id="2-cheng-gong-ru-he-ding-yi" tabindex="-1">2. 成功如何定义 <a class="header-anchor" href="#2-cheng-gong-ru-he-ding-yi" aria-label="Permalink to &quot;2. 成功如何定义&quot;">​</a></h3><ul><li>请求在哪个时间点对客户端返回成功？</li><li>成功是否意味着已经持久化、完成复制或仅进入队列？</li><li>客户端超时后重试是否安全？</li></ul><h3 id="3-shun-xu-ru-he-jian-li" tabindex="-1">3. 顺序如何建立 <a class="header-anchor" href="#3-shun-xu-ru-he-jian-li" aria-label="Permalink to &quot;3. 顺序如何建立&quot;">​</a></h3><ul><li>业务是否真的需要全局顺序，还是每个用户、订单或分区内有序即可？</li><li>顺序来自单个 Leader、逻辑时钟还是消息代理的分区？</li><li>并发冲突如何被发现和处理？</li></ul><h3 id="4-gu-zhang-ru-he-ge-chi" tabindex="-1">4. 故障如何隔离 <a class="header-anchor" href="#4-gu-zhang-ru-he-ge-chi" aria-label="Permalink to &quot;4. 故障如何隔离&quot;">​</a></h3><ul><li>如果下游变慢，上游会超时、排队还是继续重试？</li><li>是否设置了请求截止时间、重试预算和最大队列长度？</li><li>单个租户、分区或可用区故障会影响多大范围？</li></ul><h3 id="5-ru-he-zheng-ming-pan-duan" tabindex="-1">5. 如何证明判断 <a class="header-anchor" href="#5-ru-he-zheng-ming-pan-duan" aria-label="Permalink to &quot;5. 如何证明判断&quot;">​</a></h3><ul><li>哪个指标先显示异常？</li><li>能否通过链路找到具体慢调用？</li><li>能否使用 <code>trace_id</code> 在日志中还原业务上下文？</li><li>遥测管道自身发生故障时能否被发现？</li></ul><p>最后一组问题就是<a href="./observability.html">分布式可观测性</a>要解决的核心。</p><h2 id="tui-jian-xue-xi-shun-xu" tabindex="-1">推荐学习顺序 <a class="header-anchor" href="#tui-jian-xue-xi-shun-xu" aria-label="Permalink to &quot;推荐学习顺序&quot;">​</a></h2><ol><li><strong>先理解失败语义</strong>：超时不代表失败，重试不天然安全。</li><li><strong>再理解时间与顺序</strong>：学习因果关系、逻辑时钟和一致性模型。</li><li><strong>再学习复制与共识</strong>：先掌握 Leader、日志复制和多数派，再阅读 Raft。</li><li><strong>把可靠性落到运行时</strong>：学习限流、隔离、降级和 SLO。</li><li><strong>用可观测性验证理解</strong>：依次阅读<a href="./observability.html">可观测性总览</a>、<a href="./observability-trace.html">分布式链路追踪</a>和<a href="./observability-log.html">分布式日志</a>。</li></ol><h2 id="xue-xi-zi-ce" tabindex="-1">学习自测 <a class="header-anchor" href="#xue-xi-zi-ce" aria-label="Permalink to &quot;学习自测&quot;">​</a></h2><ol><li>客户端调用支付服务超时，为什么不能直接认定支付失败？</li><li>CAP 中的“一致性”和数据库 ACID 中的“一致性”是否是同一个概念？</li><li>为什么物理时间戳不足以证明两个跨节点事件的因果关系？</li><li>一个五节点 Raft 集群为什么通常能容忍两个节点不可用？</li><li>如果链路显示数据库调用很慢，还需要查看哪些日志和指标才能继续判断原因？</li></ol><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>Leslie Lamport：<a href="https://www.microsoft.com/en-us/research/publication/time-clocks-ordering-events-distributed-system/" target="_blank" rel="noreferrer">Time, Clocks and the Ordering of Events in a Distributed System</a></li><li>Seth Gilbert、Nancy Lynch：<a href="https://www.comp.nus.edu.sg/~gilbert/pubs/BrewersConjecture-SigAct.pdf" target="_blank" rel="noreferrer">Brewer&#39;s Conjecture and the Feasibility of Consistent, Available, Partition-Tolerant Web Services</a></li><li>Michael J. Fischer、Nancy A. Lynch、Michael S. Paterson：<a href="https://groups.csail.mit.edu/tds/papers/Lynch/jacm85.pdf" target="_blank" rel="noreferrer">Impossibility of Distributed Consensus with One Faulty Process</a></li><li>Diego Ongaro、John Ousterhout：<a href="https://raft.github.io/raft.pdf" target="_blank" rel="noreferrer">In Search of an Understandable Consensus Algorithm</a></li><li>Jeffrey Dean、Sanjay Ghemawat：<a href="https://research.google/pubs/mapreduce-simplified-data-processing-on-large-clusters/" target="_blank" rel="noreferrer">MapReduce: Simplified Data Processing on Large Clusters</a></li><li>Google SRE Book：<a href="https://sre.google/sre-book/monitoring-distributed-systems/" target="_blank" rel="noreferrer">Monitoring Distributed Systems</a></li><li>Amazon Builders&#39; Library：<a href="https://aws.amazon.com/builders-library/timeouts-retries-and-backoff-with-jitter/" target="_blank" rel="noreferrer">Timeouts, retries and backoff with jitter</a></li></ul>',34))])}const B=l(c,[["render",E]]);export{k as __pageData,B as default};
